{"source": "def investigate(context, acquire):
    hist = acquire('history')
    # Family: put in {ignore, replace, upsert}, trigger in {none, after_insert},
    # channel in {changes, total_main, total_main+total_other}
    # We simulate all 18 members and keep those matching all receipts.

    def simulate(put_mode, trig, chan, actions):
        # returns (channel_value, committed_count, committed_sum)
        # state: dict key->value for committed main db
        # other db separate committed state
        main = {}
        other = {}
        # transaction state per connection: None or dict (working copy)
        tx = {'main': None, 'other': None}
        # total_changes counters
        tc = {'main': 0, 'other': 0}
        # last changes() per connection
        last_ch = {'main': 0, 'other': 0}

        def do_write(conn, key, val, mode):
            # mode: 'put' or 'update'
            db = main if conn == 'main' else other
            work = tx[conn] if tx[conn] is not None else db
            changed = 0
            if mode == 'put':
                if key in work:
                    if put_mode == 'ignore':
                        changed = 0
                    elif put_mode == 'replace':
                        work[key] = val
                        changed = 1
                    else:  # upsert
                        work[key] = val
                        changed = 1
                else:
                    work[key] = val
                    changed = 1
            else:  # update
                if key in work:
                    work[key] = val
                    changed = 1
                else:
                    changed = 0
            # trigger: AFTER INSERT fires only on actual insert (new row)
            # For put: insert happens when key not in work (all modes) OR replace/upsert on existing?
            # INSERT OR REPLACE on existing key: it deletes then inserts -> AFTER INSERT fires.
            # ON CONFLICT DO UPDATE: it's an UPDATE, not INSERT -> AFTER INSERT does not fire.
            # INSERT OR IGNORE on existing: no insert -> no trigger.
            trig_fired = 0
            if mode == 'put':
                if key not in work:
                    trig_fired = 1
                else:
                    if put_mode == 'replace':
                        trig_fired = 1
                    elif put_mode == 'upsert':
                        trig_fired = 0
                    else:
                        trig_fired = 0
            # update never fires AFTER INSERT
            # total_changes counts direct changes + trigger changes
            direct = changed
            trig_changes = trig_fired if trig == 'after_insert' else 0
            tc[conn] += direct + trig_changes
            last_ch[conn] = direct + trig_changes
            return

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                if tx[conn] is None:
                    db = main if conn == 'main' else other
                    tx[conn] = dict(db)
            elif op == 'commit':
                if tx[conn] is not None:
                    db = main if conn == 'main' else other
                    db.clear()
                    db.update(tx[conn])
                    tx[conn] = None
            elif op == 'rollback':
                tx[conn] = None
            elif op == 'put':
                do_write(conn, act['key'], act['value'], 'put')
            elif op == 'update':
                do_write(conn, act['key'], act['value'], 'update')
            elif op == 'delete':
                db = main if conn == 'main' else other
                work = tx[conn] if tx[conn] is not None else db
                if act['key'] in work:
                    del work[act['key']]
                    changed = 1
                else:
                    changed = 0
                tc[conn] += changed
                last_ch[conn] = changed

        # committed state: main db (separate reader sees committed main)
        # Note: other connection writes to same database? The problem says
        # 'fresh main/other database connections' and 'the other connection can write'.
        # It seems both connections operate on the same database (items table).
        # But committed state read through separate connection sees main's committed state.
        # Actually 'other' is a second connection to the same database.
        # So committed state should be the merged committed state.
        # However, transactions on main and other are independent.
        # Let's assume both write to the same underlying database.
        # We need to merge: committed state is the database state.
        # But our simulation kept main and other separate. Let's fix: both share the same db.
        # Re-simulate with shared db.
        return None

    # Redo simulation with shared database
    def simulate2(put_mode, trig, chan, actions):
        db = {}
        tx = {'main': None, 'other': None}
        tc = {'main': 0, 'other': 0}
        last_ch = {'main': 0, 'other': 0}

        def do_write(conn, key, val, mode):
            work = tx[conn] if tx[conn] is not None else db
            changed = 0
            trig_fired = 0
            if mode == 'put':
                if key in work:
                    if put_mode == 'ignore':
                        changed = 0
                    elif put_mode == 'replace':
                        work[key] = val
                        changed = 1
                        trig_fired = 1
                    else:
                        work[key] = val
                        changed = 1
                        trig_fired = 0
                else:
                    work[key] = val
                    changed = 1
                    trig_fired = 1
            else:
                if key in work:
                    work[key] = val
                    changed = 1
                else:
                    changed = 0
            direct = changed
            trig_changes = trig_fired if trig == 'after_insert' else 0
            tc[conn] += direct + trig_changes
            last_ch[conn] = direct + trig_changes

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                if tx[conn] is None:
                    tx[conn] = dict(db)
            elif op == 'commit':
                if tx[conn] is not None:
                    db.clear()
                    db.update(tx[conn])
                    tx[conn] = None
            elif op == 'rollback':
                tx[conn] = None
            elif op == 'put':
                do_write(conn, act['key'], act['value'], 'put')
            elif op == 'update':
                do_write(conn, act['key'], act['value'], 'update')
            elif op == 'delete':
                work = tx[conn] if tx[conn] is not None else db
                if act['key'] in work:
                    del work[act['key']]
                    changed = 1
                else:
                    changed = 0
                tc[conn] += changed
                last_ch[conn] = changed

        if chan == 'changes':
            ch = last_ch['main']
        elif chan == 'total_main':
            ch = tc['main']
        else:
            ch = tc['main'] + tc['other']
        cnt = len(db)
        sm = sum(db.values())
        return (ch, cnt, sm)

    # Filter family members
    put_modes = ['ignore', 'replace', 'upsert']
    trigs = ['none', 'after_insert']
    chans = ['changes', 'total_main', 'total_other']

    candidates = []
    for pm in put_modes:
        for tg in trigs:
            for ch in chans:
                ok = True
                for rec in hist:
                    acts = rec['actions']
                    obs = rec['observed']
                    try:
                        c, cnt, sm = simulate2(pm, tg, ch, acts)
                    except Exception:
                        ok = False
                        break
                    if c != obs['channel'] or cnt != obs['committed_count'] or sm != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, tg, ch))

    goal = context['goal']
    actions = context['actions']

    if not candidates:
        return {'value': None, 'unresolved': True}

    vals = set()
    for pm, tg, ch in candidates:
        c, cnt, sm = simulate2(pm, tg, ch, actions)
        if goal == 'channel':
            vals.add(c)
        elif goal == 'committed_count':
            vals.add(cnt)
        else:
            vals.add(sm)

    if len(vals) == 1:
        return {'value': vals.pop(), 'unresolved': False}
    return {'value': None, 'unresolved': True}
", "scope": "The source's put mode, trigger presence, and channel are inferred by simulating all 18 family members against calibration receipts; only members matching every receipt are retained. The goal is resolved only if all retained members predict the same value.", "lesson": "Calibration receipts uniquely constrain the family member when they include discriminating cases like repeated puts, updates, deletes, and cross-connection writes. The channel is not net committed effects: changes() reflects the last statement's direct row changes plus trigger changes, while total_changes accumulates across statements and connections."}
